impl HostLibraryRuntimeGuard {
    fn enter(depth: &mut usize) -> Self {
        *depth = depth.saturating_add(1);
        Self { depth }
    }
}

impl Drop for HostLibraryRuntimeGuard {
    fn drop(&mut self) {
        unsafe {
            *self.depth = (*self.depth).saturating_sub(1);
        }
    }
}

