    fn check_malloc_call(
        &self,
        args: &[Expr],
        evaluated: &[TypedValue],
        span: Span,
    ) -> Result<(), Diagnostic> {
        if args.len() != 1 || evaluated.len() != 1 {
            return Err(Diagnostic::error(
                "malloc requires exactly one argument",
                span,
            ));
        }
        let size = &evaluated[0];
        self.reject_missing_return_value(size, args[0].span())?;
        self.reject_indeterminate_library_value(size, args[0].span(), "malloc")?;
        if size.ty != CType::UnsignedLong {
            return Err(Diagnostic::error(
                "malloc size argument must have type unsigned long",
                args[0].span(),
            ));
        }
        let _ = usize::try_from(size.to_int()?).map_err(|_| {
            Diagnostic::error("malloc size is out of supported range", args[0].span())
        })?;
        Ok(())
    }

    fn check_abs_call(
        &self,
        function_name: &'static str,
        args: &[Expr],
        evaluated: &[TypedValue],
        expected: &CType,
        span: Span,
    ) -> Result<(), Diagnostic> {
        if args.len() != 1 || evaluated.len() != 1 {
            return Err(Diagnostic::error(
                format!("{function_name} requires exactly one argument"),
                span,
            ));
        }
        let value = &evaluated[0];
        self.reject_missing_return_value(value, args[0].span())?;
        self.reject_indeterminate_library_value(value, args[0].span(), function_name)?;
        if &value.ty != expected {
            return Err(Diagnostic::error(
                format!("{function_name} requires an argument of type {expected}"),
                args[0].span(),
            ));
        }
        let int_value = value.to_int()?;
        if int_value < 0 {
            let _ =
                self.ensure_integer_ub_range(-int_value, expected, args[0].span(), "7.20.6.1")?;
        }
        Ok(())
    }

    fn char_ptr_ptr_type(&self) -> CType {
        CType::pointer_to(self.char_ptr_type())
    }

    fn wchar_type(&self) -> CType {
        CType::Int
    }

    fn wchar_ptr_type(&self) -> CType {
        CType::pointer_to(self.wchar_type())
    }

    fn const_wchar_ptr_type(&self) -> CType {
        CType::pointer_to(CType::qualified(
            self.wchar_type(),
            crate::types::TypeQualifiers {
                is_const: true,
                is_restrict: false,
                is_volatile: false,
            },
        ))
    }

