    #[test]
    fn quoted_includes_resolve_relative_to_the_including_file() {
        let dir = temp_test_dir("include-relative");
        let nested = dir.join("dir");
        fs::create_dir_all(&nested).unwrap();
        fs::write(
            dir.join("main.c"),
            "#include <stdio.h>\n#include \"dir/inner.h\"\nint main(void) { printf(\"%d\\n\", VALUE); return 0; }\n",
        )
        .unwrap();
        fs::write(nested.join("inner.h"), "#include \"value.h\"\n").unwrap();
        fs::write(nested.join("value.h"), "#define VALUE 9\n").unwrap();

        let result = run_file(dir.join("main.c")).unwrap();
        assert_eq!(result.stdout, "9\n");

        let _ = fs::remove_dir_all(dir);
    }

