    #[test]
    fn floating_point_arithmetic_calls_and_sizes_work() {
        let source = r#"
            #include <stdio.h>
            float sum(float x, float y) { return x + y; }
            long double twice(long double x) { return x * 2.0L; }

            int main(void) {
                float a = 1.25f;
                double b = 2.25;
                long double c = 1.5L;
                printf("%f %f %Lf %d %lu %lu %lu\n",
                       a + b,
                       sum(a, b),
                       twice(c),
                       (_Bool)0.5,
                       sizeof(float),
                       sizeof(double),
                       sizeof(long double));
                return 0;
            }
        "#;
        let result = run_source("test.c", source).unwrap();
        assert_eq!(result.stdout, "3.500000 3.500000 3.000000 1 4 8 8\n");
    }

