    #[test]
    fn static_functions_with_same_name_in_different_files_do_not_conflict() {
        let dir = temp_test_dir("static-functions");
        fs::create_dir_all(&dir).unwrap();
        let main_file = dir.join("main.c");
        let helper_file = dir.join("helper.c");
        fs::write(
            &main_file,
            r#"
                #include <stdio.h>

                int f(void);

                static int helper(void) {
                    return 2;
                }

                int main(void) {
                    printf("%d %d\n", f(), helper());
                    return 0;
                }
            "#,
        )
        .unwrap();
        fs::write(
            &helper_file,
            r#"
                static int helper(void) {
                    return 1;
                }

                int f(void) {
                    return helper();
                }

            "#,
        )
        .unwrap();
        let result = run_files([main_file, helper_file]).unwrap();
        assert_eq!(result.stdout, "1 2\n");
    }

    #[test]
