    #[test]
    fn goto_forward_jump_reaches_later_label() {
        let source = r#"
            #include <stdio.h>
            int main(void) {
                goto out;
                printf("bad\n");
            out:
                printf("ok\n");
                return 0;
            }
        "#;
        let result = run_source("test.c", source).unwrap();
        assert_eq!(result.stdout, "ok\n");
    }

    #[test]
    fn goto_backward_jump_reaches_earlier_label() {
        let source = r#"
            #include <stdio.h>
            int main(void) {
                int i = 0;
            loop:
                i++;
                if (i < 3) {
                    goto loop;
                }
                printf("%d\n", i);
                return 0;
            }
        "#;
        let result = run_source("test.c", source).unwrap();
        assert_eq!(result.stdout, "3\n");
    }

    #[test]
    fn goto_can_enter_a_nested_if_branch() {
        let source = r#"
            #include <stdio.h>
            int main(void) {
                int x = 0;
                int jumped = 0;
                if (0) {
                label:
                    x = 5;
                }
                if (!jumped) {
                    jumped = 1;
                    goto label;
                }
                printf("%d\n", x);
                return 0;
            }
        "#;
        let result = run_source("test.c", source).unwrap();
        assert_eq!(result.stdout, "5\n");
    }

    #[test]
    fn goto_can_enter_a_while_body() {
        let source = r#"
            #include <stdio.h>
            int main(void) {
                int i = 0;
                int jumped = 0;
                while (i < 3) {
                label:
                    i++;
                    if (i < 3) {
                        continue;
                    }
                    break;
                }
                if (!jumped) {
                    jumped = 1;
                    goto label;
                }
                printf("%d\n", i);
                return 0;
            }
        "#;
        let result = run_source("test.c", source).unwrap();
        assert_eq!(result.stdout, "4\n");
    }

