    #[test]
    fn variadic_function_with_stdarg_utilities_works() {
        let source = r#"
            #include <stdio.h>
            #include <stdarg.h>

            int sum(int count, ...) {
                va_list ap;
                va_start(ap, count);
                int total = 0;
                while (count) {
                    total += va_arg(ap, int);
                    count--;
                }
                va_end(ap);
                return total;
            }

            int main(void) {
                printf("%d\n", sum(4, 1, 2, 3, 4));
                return 0;
            }
        "#;
        let result = run_source("test.c", source).unwrap();
        assert_eq!(result.stdout, "10\n");
    }

    #[test]
    fn va_copy_clones_the_cursor() {
        let source = r#"
            #include <stdio.h>
            #include <stdarg.h>

            int test(int count, ...) {
                va_list ap;
                va_list copy;
                va_start(ap, count);
                va_copy(copy, ap);
                int a = va_arg(ap, int);
                int b = va_arg(copy, int);
                va_end(copy);
                va_end(ap);
                return a + b;
            }

            int main(void) {
                printf("%d\n", test(2, 7, 11));
                return 0;
            }
        "#;
        let result = run_source("test.c", source).unwrap();
        assert_eq!(result.stdout, "14\n");
    }

