    #[test]
    fn qsort_and_bsearch_work_with_user_comparator() {
        let source = r#"
            #include <stdio.h>
            #include <stdlib.h>

            int cmp(const void *lhs, const void *rhs) {
                int a = *(const int *)lhs;
                int b = *(const int *)rhs;
                return (a > b) - (a < b);
            }

            int main(void) {
                int values[4] = { 3, 1, 4, 2 };
                int key = 3;
                qsort(values, 4, sizeof(int), cmp);
                int *found = bsearch(&key, values, 4, sizeof(int), cmp);
                printf("%d %d %d %d %d\n",
                    values[0], values[1], values[2], values[3],
                    found != 0 ? *found : -1);
                return 0;
            }
        "#;
        let result = run_source("test.c", source).unwrap();
        assert_eq!(result.stdout, "1 2 3 4 3\n");
    }

